/* Reservation preview: no customer data is persisted or sent to a server. */
function rentalDate(offset=0){const d=new Date();d.setDate(d.getDate()+offset);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function validateRentalDates(values,today=rentalDate()){return values.pickupDate>=today&&new Date(values.returnDate+'T'+values.returnTime)-new Date(values.pickupDate+'T'+values.pickupTime)>=86400000;}
function initReservationFlow(data){
 const root=document.querySelector('.rental-flow'),id=Number(new URLSearchParams(location.search).get('vehicle')),v=data.fleet.find(x=>x.id===id);
 if(!v){root.innerHTML='<div class="rental-empty"><h1>Find Your Ideal Ride</h1><p>Choose a vehicle from our fleet to start your reservation preview.</p><a class="btn blue" href="fleet.html">View full fleet</a></div>';return;}
 let saved={};try{saved=JSON.parse(sessionStorage.getItem('sxm-trip'))||{};}catch{}
 const money=n=>'$'+Number(n).toLocaleString('en-US',{minimumFractionDigits:2}),name=v.brand+' '+v.model.trim();let step=0,values={};
 const field=(label,key,type='text',required=false,extra='')=>`<label class="rental-field"><span>${label}${required?' <span aria-hidden="true">*</span>':''}</span><input name="${key}" type="${type}" ${required?'required':''} ${extra}></label>`;
 const loc=(label,key)=>`<label class="rental-field">${label}<select name="${key}" required>${data.bookingLocations.map(l=>`<option value="${esc(l.value)}">${esc(l.label)}</option>`).join('')}</select></label>`;
 const time=(label,key)=>`<label class="rental-field">${label}<select name="${key}" required>${Array.from({length:19},(_,i)=>{const h=8+Math.floor(i/2),t=String(h).padStart(2,'0')+':'+(i%2?'30':'00');return `<option value="${t}">${timeLabel(t)}</option>`;}).join('')}</select></label>`;
 const specs=[['Passengers',v.numberOfPassengers],['Luggage',v.amountOfLuggage],['Doors',v.numberOfDoors],['Transmission',v.transmission||'Not specified'],['Air conditioning',v.hasAirConditioning?'Included':'Not specified'],['Multimedia unit',v.hasMultiMediaUnit?'Included':'Not specified']];
 root.innerHTML=`<div class="rental-page-heading"><div><h1>Your Journey, Made Simple</h1><p>A few details now. A little more freedom ahead.</p></div></div><ol class="rental-steps" aria-label="Reservation progress">${['Vehicle','Reservation','Review'].map((t,i)=>`<li><button type="button" data-rental-step="${i}"><span>${i+1}</span>${t}</button></li>`).join('')}</ol><div class="rental-layout"><div class="rental-primary"><section data-rental-panel="0" class="rental-surface"><div class="rental-section-heading"><h2>Meet Your Ride</h2></div><div class="rental-vehicle-stage"><img src="${esc(v.cardImage||v.image)}" alt="${esc(name)}" width="600" height="350"></div><h3>${esc(name)}</h3><p>${esc(v.description)}</p><dl class="rental-spec-grid">${specs.map(([k,x])=>`<div><dt>${k}</dt><dd>${esc(x)}</dd></div>`).join('')}</dl><div class="rental-bottom-actions"><a href="fleet.html">Choose another car</a><button class="btn blue" type="button" data-rental-next>Continue</button></div></section><form data-rental-panel="1" class="rental-surface" hidden><div class="rental-section-heading"><span class="rental-step-label">02 / YOUR RESERVATION</span><h2>Make It Your Journey</h2><p>Fields marked * are required for this preview.</p></div><fieldset><legend>Pick-up & Return</legend><div class="rental-form-grid">${loc('Pick-up location','pickupLocation')}${loc('Return location','returnLocation')}${field('Pick-up date','pickupDate','date',true,`min="${rentalDate()}"`)}${field('Return date','returnDate','date',true,`min="${rentalDate()}"`)}${time('Pick-up time','pickupTime')}${time('Return time','returnTime')}</div><p class="rental-form-error" id="rental-date-error" role="alert"></p></fieldset><fieldset><legend>A Little Extra For Your Trip</legend><p>Optional extras. Pricing and availability require the company’s booking connection.</p><div class="rental-extras">${data.options.map((o,i)=>`<div class="rental-extra"><label>${o.usesAmount?`<select name="extra${i}" aria-label="${esc(o.name)} quantity">${Array.from({length:o.amountMax+1},(_,n)=>`<option value="${n}">${n}</option>`).join('')}</select>`:`<input type="checkbox" name="extra${i}" value="1">`}<span>${esc(o.name)}</span></label><details><summary>Details</summary><p>${esc(o.description)}</p></details></div>`).join('')}</div></fieldset><fieldset><legend>Contact Details</legend><div class="rental-form-grid">${field('First name','firstName','text',true,'minlength="2" autocomplete="given-name"')}${field('Last name','lastName','text',true,'minlength="2" autocomplete="family-name"')}${field('Email address','email','email',true,'autocomplete="email"')}${field('Confirm email address','emailVerify','email',true)}${field('Country calling code','countryDialCode','tel',true,'placeholder="e.g. +1" pattern="[+][0-9]{1,4}"')}${field('Phone number','telephone','tel',true,'autocomplete="tel-national"')}${field('How did you hear about us?','heardAbout','text',true)}</div></fieldset><details class="rental-driver-details"><summary>Address & Driver Details <span>Optional in this preview</span></summary><p>The company may require these details to complete your rental.</p><div class="rental-form-grid">${field('Street address','renterAddress1')}${field('Country','country')}${field('State / region','state')}${field('Postal code','zipCode')}${field('Driver’s license number','licenseNumber')}${field('License expiration date','licenseExpDate','date')}${field('Date of birth','dateOfBirth','date',false,`max="${rentalDate()}"`)}</div></details><fieldset><legend>Anything Else?</legend>${field('Coupon code (Optional)','coupon')}<small>Coupon validation will be available when live booking is connected.</small><label class="rental-field">Notes (Optional)<textarea name="notes" rows="3" maxlength="2000"></textarea></label></fieldset><div class="rental-bottom-actions"><button type="button" class="rental-back" data-rental-back>Back</button><button class="btn blue" type="submit">Review details</button></div></form><section data-rental-panel="2" class="rental-surface" hidden><div class="rental-section-heading"><span class="rental-step-label">03 / YOUR REVIEW</span><h2>One Last Look</h2><p>Review your journey before finishing this demonstration.</p></div><div id="rental-review"></div><form id="rental-review-form"><div class="rental-policy"><label><input type="checkbox" required> <span>I have read the <a href="${BASE}assets/documents/Dollar_Thrifty_Terms_and_Conditions.pdf" target="_blank" rel="noopener">Terms and Conditions</a>.</span></label><label><input type="checkbox" required> <span>I have read the <a href="${BASE}assets/documents/Dollar_Thrifty_Rental_Policies.pdf" target="_blank" rel="noopener">Rental Policies</a>.</span></label></div><div class="rental-bottom-actions"><button type="button" class="rental-back" data-rental-back>Edit details</button><button class="btn blue" type="submit">Finish preview</button></div></form></section><section data-rental-panel="3" class="rental-surface rental-finished" hidden><span class="rental-finish-icon" aria-hidden="true">✓</span><h2>Your Preview Is Complete</h2><p>You’ve reached the end of the redesigned booking experience. No reservation has been made and no confirmation email has been sent.</p><p>For a real reservation, continue to the company’s current booking website. You’ll need to enter your details there.</p><a class="btn blue" href="${BASE}">Open live booking</a><a href="fleet.html">Back to the fleet</a></section></div><aside class="rental-summary rental-surface" aria-label="Selected vehicle"><span class="rental-summary-label">Your selected ride</span><img src="${esc(v.cardImage||v.image)}" alt="" width="600" height="350"><span class="rental-category">${esc(v.type)}</span><h2>${esc(name)}</h2><p>${v.numberOfPassengers} passengers <span aria-hidden="true">·</span> ${esc(v.transmission||'Transmission not specified')}</p><div class="rental-published-rate">${v.publishedRate?`<div><strong>${money(v.publishedRate.day)}</strong><span>/ day</span></div><small>${money(v.publishedRate.week)} / week</small>`:'<strong>Rates on request</strong>'}</div><p class="rental-rate-note">Published reference rates. Live availability, extras, taxes and the final total require the company’s booking connection.</p><div id="rental-trip-mini"></div><a class="rental-help" href="tel:+17215452393">Need a hand? +1 (721) 545-2393</a></aside></div>`;
 const form=root.querySelector('[data-rental-panel="1"]');
 for(const [key,val] of Object.entries({pickupDate:rentalDate(1),returnDate:rentalDate(4),pickupTime:'10:00',returnTime:'10:00',...saved})){const el=form.elements.namedItem(key);if(el&&typeof val==='string')el.value=val;}
 const email=form.elements.emailVerify;email.addEventListener('input',()=>email.setCustomValidity(''));form.elements.email.addEventListener('input',()=>email.setCustomValidity(''));
 function show(n){step=n;root.querySelectorAll('[data-rental-panel]').forEach(p=>p.hidden=Number(p.dataset.rentalPanel)!==n);root.querySelectorAll('[data-rental-step]').forEach((b,i)=>{b.disabled=i>step;b.closest('li').classList.toggle('is-current',i===Math.min(n,2));b.closest('li').classList.toggle('is-complete',i<n);if(i===Math.min(n,2))b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});if(n===2)renderReview();if(n===3){root.querySelector('.rental-steps').hidden=true;form.reset();values={};root.querySelector('#rental-review').innerHTML='';}if(n>0){const h=root.querySelector(`[data-rental-panel="${n}"] h2`);h.tabIndex=-1;h.focus({preventScroll:true});root.querySelector('.rental-steps').scrollIntoView({block:'start',behavior:'smooth'});}}
 function renderReview(){const extras=data.options.map((o,i)=>Number(values['extra'+i])?`${o.name}${o.usesAmount?' × '+values['extra'+i]:''}`:'').filter(Boolean);const row=(k,x)=>`<div><dt>${k}</dt><dd>${esc(x)}</dd></div>`;root.querySelector('#rental-review').innerHTML=`<div class="rental-review-block"><h3>Your Trip</h3><dl>${row('Vehicle',name)}${row('Pick-up',values.pickupLocation+' · '+values.pickupDate+' · '+timeLabel(values.pickupTime))}${row('Return',values.returnLocation+' · '+values.returnDate+' · '+timeLabel(values.returnTime))}</dl></div><div class="rental-review-block"><h3>Contact Details</h3><dl>${row('Name',values.firstName+' '+values.lastName)}${row('Email',values.email)}${row('Phone',values.countryDialCode+' '+values.telephone)}${row('How you heard about us',values.heardAbout)}</dl></div><div class="rental-review-block"><h3>Extras & Notes</h3><p>${esc(extras.join(', ')||'No extras selected')}</p>${values.notes?`<p>${esc(values.notes)}</p>`:''}${values.coupon?`<p>Coupon: ${esc(values.coupon)} (not validated)</p>`:''}</div>${['renterAddress1','country','state','zipCode','licenseNumber','licenseExpDate','dateOfBirth'].some(k=>values[k])?`<div class="rental-review-block"><h3>Address & Driver Details</h3><dl>${[['Address','renterAddress1'],['Country','country'],['State / region','state'],['Postal code','zipCode'],['License number','licenseNumber'],['License expiration','licenseExpDate'],['Date of birth','dateOfBirth']].filter(([,k])=>values[k]).map(([label,key])=>row(label,values[key])).join('')}</dl></div>`:''}`;root.querySelector('#rental-trip-mini').innerHTML=`<div class="rental-mini-trip"><strong>Your Trip</strong><p>Pick-up<br>${esc(values.pickupLocation)}<br>${esc(values.pickupDate)} · ${esc(timeLabel(values.pickupTime))}</p><p>Return<br>${esc(values.returnLocation)}<br>${esc(values.returnDate)} · ${esc(timeLabel(values.returnTime))}</p></div>`;}
 root.querySelector('[data-rental-next]').addEventListener('click',()=>show(1));root.querySelectorAll('[data-rental-back]').forEach(b=>b.addEventListener('click',()=>show(Math.max(0,step-1))));root.querySelectorAll('[data-rental-step]').forEach(b=>b.addEventListener('click',()=>show(Number(b.dataset.rentalStep))));
 form.addEventListener('submit',e=>{e.preventDefault();values=Object.fromEntries(new FormData(form));if(values.email!==values.emailVerify){email.setCustomValidity('Please enter the same email address.');email.reportValidity();return;}if(!validateRentalDates(values)){root.querySelector('#rental-date-error').textContent='Choose a future pick-up date and return at least 24 hours after pick-up.';form.elements.returnDate.focus();return;}root.querySelector('#rental-date-error').textContent='';show(2);});
 root.querySelector('#rental-review-form').addEventListener('submit',e=>{e.preventDefault();show(3);});show(0);
}
